"""RoboPaint trajectory record and camera-calibrated controller. No privileged state."""
import os,sys,json,time
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT='/app/output'
class Painter:
 def __init__(self):
  self.r=Robot();self.obs=self.r.get_obs(cameras=[]);self.pose=self.obs.group('tcp_pose',now=True);self.q=self.obs.group('joint_pos',now=True);self.quat=np.array([0.,1.,0.,0.]);self.index=len(list(__import__('pathlib').Path(ROOT).glob('action_*.npz')))
 def send(self,p,precise=False,cameras=()):
  p=np.asarray(p);self.index+=1
  if precise:
   qs=[]
   for a in p:
    k=self.r.ik({'tip':a},seed=self.q,tol_pos_m=0.000005,tol_rot_rad=0.0001,max_iters=200)
    if not k['ok']:raise RuntimeError(k)
    self.q=np.array(k['q']);qs.append(self.q)
   actions=np.array(qs);typ='joint_position'
  else:actions=p;typ='ee_pose'
  np.savez(f'{ROOT}/action_{self.index:04d}.npz',actions=actions,tip_targets=p,action_type=typ,dt=.05)
  before=self.r.status()
  try:o=self.r.submit(typ,actions,dt=.05,video='none',cameras=list(cameras))
  except Exception:
   status=self.r.wait_ready();print('RESUMED',before,status,flush=True);raise
  self.pose=o.group('tcp_pose',now=True);self.q=o.group('joint_pos',now=True)
  json.dump(o.meta,open(f'{ROOT}/action_{self.index:04d}.json','w'))
  for c,a in o.last.items():Image.fromarray(a).save(f'{ROOT}/{c}.png')
  print('action',self.index,'n',len(p),'tip',np.round(self.pose[:3],6),'left',o.meta.get('time_left_s'),'plan',o.meta.get('plan'),flush=True)
  return o
 def move(self,xyz,speed=.04,hold=.3,precise=False):
  dest=np.r_[xyz,self.quat];n=max(1,int(np.ceil(np.linalg.norm(dest[:3]-self.pose[:3])/speed/.05)))
  p=np.linspace(np.r_[self.pose[:3],self.quat],dest,n+1)[1:];p=np.vstack([p,np.tile(dest,(int(hold/.05),1))])
  for a in range(0,len(p),180):self.send(p[a:a+180],precise=precise)
 def dip(self):
  self.move([self.pose[0],self.pose[1],.075]);self.move([-.1,.151,.075]);self.move([-.1,.151,.024],hold=.7);self.move([-.1,.151,.075])
 def observe(self,name,cameras=['canvas_cam','practice_cam','scene_cam','side_cam']):
  o=self.r.get_obs(cameras=cameras,depth=True);o.save(f'{ROOT}/{name}')
  for c,a in o.last.items():Image.fromarray(a).save(f'{ROOT}/{name}_{c}.png')
  return o
if __name__=='__main__':
 p=Painter()
 if sys.argv[1]=='calibrate':
  p.dip()
  for i,dep in enumerate([.0003,.0007,.0015,.003,.005,.008]):
   x=.0-i*.025;y=-.16;z=.0202-dep
   p.move([x,y,.055]);p.move([x,y,z],speed=.01,hold=.3,precise=True)
   p.move([x,y-.035,z],speed=.012,hold=.2,precise=True)
   p.move([x,y-.035,.055],speed=.01)
  p.move([-.1,.15,.075]);p.observe('calibration')
